{
  "name": "Benchmark Intermediate Reconciliation",
  "version": 1,
  "datasets": [
    "BM_INTERMEDIATE_GL",
    "BM_INTERMEDIATE_BANK"
  ],
  "rules": [
    {
      "id": "INT_EXACT_REF_AMT_DATE",
      "type": "exact",
      "datasets": [
        "BM_INTERMEDIATE_GL",
        "BM_INTERMEDIATE_BANK"
      ],
      "keys": [
        {
          "type": "text",
          "match_mode": "exact",
          "fields": {
            "BM_INTERMEDIATE_GL": "reference",
            "BM_INTERMEDIATE_BANK": "bank_reference"
          }
        },
        {
          "type": "amount",
          "match_mode": "exact",
          "fields": {
            "BM_INTERMEDIATE_GL": "amount",
            "BM_INTERMEDIATE_BANK": "amount"
          }
        },
        {
          "type": "date",
          "match_mode": "exact",
          "fields": {
            "BM_INTERMEDIATE_GL": "posting_date",
            "BM_INTERMEDIATE_BANK": "value_date"
          }
        }
      ],
      "remarks": "Pass 1: Exact Reference + Amount + Date"
